function FORCED-STAR-AT-VERTEX(incident_colors, targets):
  q <- length(targets)
  counts <- array of q zeros
  for c in incident_colors:
      counts[c] <- counts[c] + 1
      if counts[c] >= targets[c]:
          return c            # color of forced monochromatic star
  return NONE                 # no target met (only if below threshold)

function COMPLETE-GRAPH-STAR-THRESHOLD(targets):
  return sum over j of max(targets[j]-1, 0) + 2

function FORCES-ON-COMPLETE-GRAPH(n, targets):
  return n >= COMPLETE-GRAPH-STAR-THRESHOLD(targets)

